import{_ as t,o,c as a,a2 as d}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"How do I add my first ESPHome device?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/01.erste-schritte/03.erstes-geraet.md"},"headers":[],"relativePath":"adapter/esphome/erste-schritte/erstes-geraet.md","filePath":"adapter/esphome/erste-schritte/erstes-geraet.md","lastUpdated":1795571670000}'),n={name:"adapter/esphome/erste-schritte/erstes-geraet.md"};function i(s,e,r,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="how-do-i-add-my-first-esphome-device" tabindex="-1">How do I add my first ESPHome device? <a class="header-anchor" href="#how-do-i-add-my-first-esphome-device" aria-label="Permalink to &quot;How do I add my first ESPHome device?&quot;">​</a></h1><p><a id="add-esphome-device-adapter"></a></p><h2 id="how-do-i-add-an-esphome-device-in-the-adapter" tabindex="-1">How do I add an ESPHome device in the adapter? <a class="header-anchor" href="#how-do-i-add-an-esphome-device-in-the-adapter" aria-label="Permalink to &quot;How do I add an ESPHome device in the adapter?&quot;">​</a></h2><p>You add a device in the tab &quot;Devices&quot; of the instance settings. The instance must be running.</p><ol><li>Check that the device YAML contains <code>api:</code> and copy the key under <code>api:</code> → <code>encryption:</code> → <code>key:</code>.</li><li>Open the instance settings and the tab &quot;Devices&quot;.</li><li>Click &quot;Add device&quot;.</li><li>Enter the IP address or host name of the device and the encryption key. You only need &quot;API password (legacy)&quot; for devices without a key on ESPHome before 2026.1. If the API is not protected, leave both fields empty.</li><li>Confirm. The adapter connects and shows the result within 30 seconds.</li></ol><p>It worked when you see &quot;OK - Device successfully connected, initializing configuration&quot;. The device is then in the group &quot;Added devices&quot;, its states under <code>esphome.0.&lt;device&gt;</code>. If the device does not answer within 30 seconds, the adapter keeps trying in the background.</p><p>If discovery has already found the device, it is in the group &quot;Discovered, not added yet&quot;. Click &quot;Add&quot; there, the address is already filled in.</p><p><strong>See also:</strong> <a href="#encryption-key-not-accepted">Key not accepted</a> · <a href="#no-datapoints-shown-object-tree">No states in the object tree</a> · <a href="./../anleitungen/geraete-entdecken#auto-discovery-report-routers-foreign">Device discovery</a></p><p><a id="api-password-still-work-esphome"></a></p><h2 id="where-do-i-enter-the-api-password-and-does-it-still-work-with-esphome-2026-1" tabindex="-1">Where do I enter the API password and does it still work with ESPHome 2026.1? <a class="header-anchor" href="#where-do-i-enter-the-api-password-and-does-it-still-work-with-esphome-2026-1" aria-label="Permalink to &quot;Where do I enter the API password and does it still work with ESPHome 2026.1?&quot;">​</a></h2><p>You enter the API password in the device dialog in the field &quot;API password (legacy)&quot;, when adding the device or via &quot;Change connection settings&quot;. It is the password from <code>api:</code> → <code>password:</code> in the YAML, not the OTA password.</p><p>From ESPHome 2026.1 on there is no API password any more, only the encryption key works. If the dialog contains a key, the adapter uses only the key and ignores the password.</p><p>If the device rejects the password, the log shows <code>Device &lt;IP&gt; rejected the API password</code> and <code>info._connectionStatus</code> of the device reads <code>API password incorrect</code>.</p><p><strong>See also:</strong> <a href="#encryption-key-not-accepted">Key not accepted</a></p><p><a id="encryption-key-not-accepted"></a></p><h2 id="why-is-my-encryption-key-not-accepted" tabindex="-1">Why is my encryption key not accepted? <a class="header-anchor" href="#why-is-my-encryption-key-not-accepted" aria-label="Permalink to &quot;Why is my encryption key not accepted?&quot;">​</a></h2><p>You enter the key per device in the tab &quot;Devices&quot;, when adding it or via &quot;Change connection settings&quot;. It is in the YAML under <code>api:</code> → <code>encryption:</code> → <code>key:</code>. Copy it without quotation marks.</p><p>The log tells you what does not match:</p><table tabindex="0"><thead><tr><th>In the log</th><th>Status of the device</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Device &lt;IP&gt; requires an encryption key, …</code></td><td><code>Encryption Key Missing</code></td><td>The device requires a key, the adapter has none.</td></tr><tr><td><code>ESPHome client &lt;IP&gt; … Handshake failure</code></td><td>changes with every attempt</td><td>The key does not match the device.</td></tr></tbody></table><p>If the key does not match, open &quot;Change connection settings&quot; of the device and enter the key from the YAML currently flashed. If you leave both fields empty, the adapter keeps the stored credentials.</p><p><strong>See also:</strong> <a href="./../referenz/log-meldungen#deserializebinary-assertion-failed-bad-format">Other messages of the library</a> · <a href="./../anleitungen/geraete-verwalten#recover-stored-masked-api-password">Find the stored key</a></p><p><a id="no-datapoints-shown-object-tree"></a></p><h2 id="why-are-no-datapoints-shown-in-the-object-tree-although-the-device-runs" tabindex="-1">Why are no datapoints shown in the object tree although the device runs? <a class="header-anchor" href="#why-are-no-datapoints-shown-in-the-object-tree-although-the-device-runs" aria-label="Permalink to &quot;Why are no datapoints shown in the object tree although the device runs?&quot;">​</a></h2><p>The adapter creates states only once the device is added in the tab &quot;Devices&quot; and connected. A device that is only in the dashboard or in the group &quot;Discovered, not added yet&quot; has no states.</p><p>Do this:</p><ol><li>Check in the tab &quot;Devices&quot; that the device is listed under &quot;Added devices&quot; and connected. If not, add it.</li><li>Check that the YAML contains the entities you expect, e.g. <code>sensor:</code> or <code>switch:</code>. Only what the device reports over the API becomes a state.</li><li>Reload the tab &quot;Objects&quot;.</li></ol><p>The states are under <code>esphome.0.&lt;device&gt;.&lt;type&gt;.&lt;key&gt;</code>. <code>&lt;device&gt;</code> is the MAC address without colons, not the name from the YAML. You see the name in the column &quot;Name&quot;.</p><p><strong>See also:</strong> <a href="./../referenz/datenpunkte#datapoint-path-contain-number-instead">Structure of the state paths</a></p>',28)])])}const y=t(n,[["render",i]]);export{u as __pageData,y as default};
